-- Excel import generated from organization-accounting-2021-2026.xlsx
-- Member names converted from legacy Bijoy/SutonnyMJ encoding to Unicode.
-- Monthly payments/due amounts are imported exactly from the year sheets 2021-2025.
-- Aggregate profit/expense summaries are preserved separately because the workbook does not provide a reliable year-by-year breakdown.


create table if not exists legacy_excel_summary (id bigint generated by default as identity primary key, summary_key text not null unique, amount numeric(14,2), note text, source text, created_at timestamptz not null default now());
